    @Test
    public void testWritingBuffer1() throws IOException {
        Writer writer = new StringWriter();
        WritingBuffer buffer = new WritingBuffer(writer, 4); // 缓冲区大小为 4
        buffer.write(new char[]{'A', 'B'}, 0, 2); // 写入缓冲区
        buffer.write(new char[]{'C', 'D', 'E', 'F'}, 0, 4); // 触发 flush 分支
        buffer.write(new char[]{'G', 'H', 'I', 'J', 'K'}, 0, 5); // 直接写入底层 writer
        buffer.flush(); // 手动刷新

        Writer writer1 = new StringWriter();
        WritingBuffer buffer1 = new WritingBuffer(writer, 4); // 缓冲区大小为 4
        buffer1.write("AB", 0, 2); // 写入缓冲区
        buffer1.write("CDEF", 0, 4); // 触发 flush 分支
        buffer1.write("GHIJK", 0, 5); // 直接写入底层 writer
        buffer1.flush(); // 手动刷新

    }

    @Test
    public void testJsonValue() {
        try {
            // Test deprecated TRUE, FALSE, and NULL constants
            System.out.println("Testing deprecated constants:");
            System.out.println("TRUE: " + JsonValue.TRUE);
            System.out.println("FALSE: " + JsonValue.FALSE);
            System.out.println("NULL: " + JsonValue.NULL);

            // Test readFrom with String
            String jsonString = "{\"key\":\"value\"}";
            JsonValue jsonValueFromString = JsonValue.readFrom(jsonString);
            System.out.println("Read from String: " + jsonValueFromString);

            // Test readFrom with Reader
            StringReader reader = new StringReader(jsonString);
            JsonValue jsonValueFromReader = JsonValue.readFrom(reader);
            System.out.println("Read from Reader: " + jsonValueFromReader);

            // Test valueOf methods
            JsonValue intValue = JsonValue.valueOf(42);
            JsonValue longValue = JsonValue.valueOf(123456789L);
            JsonValue floatValue = JsonValue.valueOf(3.14f);
            JsonValue doubleValue = JsonValue.valueOf(2.71828);
            JsonValue stringValue = JsonValue.valueOf("Hello, World!");
            JsonValue booleanValueTrue = JsonValue.valueOf(true);
            JsonValue booleanValueFalse = JsonValue.valueOf(false);

            System.out.println("Value of int: " + intValue);
            System.out.println("Value of long: " + longValue);
            System.out.println("Value of float: " + floatValue);
            System.out.println("Value of double: " + doubleValue);
            System.out.println("Value of string: " + stringValue);
            System.out.println("Value of true: " + booleanValueTrue);
            System.out.println("Value of false: " + booleanValueFalse);

            // Test asObject and asArray methods
            try {
                JsonObject jsonObject = jsonValueFromString.asObject();
                System.out.println("As Object: " + jsonObject);
            } catch (UnsupportedOperationException e) {
                System.out.println("Failed asObject test: " + e.getMessage());
            }

            try {
                JsonArray jsonArray = jsonValueFromString.asArray();
                System.out.println("As Array: " + jsonArray);
            } catch (UnsupportedOperationException e) {
                System.out.println("Failed asArray test: " + e.getMessage());
            }

            // Test writeTo method
            StringWriter writer = new StringWriter();
            writer.write("\\u2028123abc\"\\");
            jsonValueFromString.writeTo(writer);
            System.out.println("Write to StringWriter: " + writer.toString());

        } catch (Exception e) {
            System.err.println("Test failed with exception: " + e.getMessage());
            e.printStackTrace();
        }
    }

