    @Test
    public void testJsonLiteral() throws NoSuchFieldException, IllegalAccessException {
        JsonLiteral jsonLiteral = new JsonLiteral("null");
        Field field = JsonLiteral.class.getDeclaredField("isNull");
        field.setAccessible(true);
        field.set(jsonLiteral, true);
        try {
            System.out.println(jsonLiteral.asBoolean());
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
        field.set(jsonLiteral, false);
        try {
            System.out.println(jsonLiteral.asBoolean());
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }

    @Test
    public void testIsHexDigit() throws NoSuchFieldException, IllegalAccessException, NoSuchMethodException, InvocationTargetException {
        JsonParser jsonParser = new JsonParser(new Json.DefaultHandler());
        Field field = JsonParser.class.getDeclaredField("current");
        field.setAccessible(true);
        field.set(jsonParser, '0');
        Method method = JsonParser.class.getDeclaredMethod("isHexDigit");
        method.setAccessible(true);
        System.out.println(method.invoke(jsonParser));
        field.set(jsonParser, 'a');
        System.out.println(method.invoke(jsonParser));
        field.set(jsonParser, 'A');
        System.out.println(method.invoke(jsonParser));
        field.set(jsonParser, 'g');
        System.out.println(method.invoke(jsonParser));
        field.set(jsonParser, '!');
        System.out.println(method.invoke(jsonParser));
        field.set(jsonParser, 'G');
        System.out.println(method.invoke(jsonParser));
        field.set(jsonParser, ']');
        System.out.println(method.invoke(jsonParser));
        field.set(jsonParser, '?');
        System.out.println(method.invoke(jsonParser));

        field.set(jsonParser, -1);
        Method method1 = JsonParser.class.getDeclaredMethod("pauseCapture");
        method1.setAccessible(true);
        try {
            System.out.println(method1.invoke(jsonParser));
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }
